  if (typeof Plotly === 'undefined') return;
  function rw(seed,n){var x=0,xs=[0],s=seed; for(var i=0;i<n;i++){s=(s*9301+49297)%233280; x += (s/233280 < 0.5 ? -1 : 1); xs.push(x); if(x>=5||x<=-5) break;} return xs;}
  var trs=[];
  var hitU=0, hitL=0;
  for(var k=0;k<40;k++){var path=rw(k*11+3,200); var t=[]; for(var i=0;i<path.length;i++) t.push(i); var last=path[path.length-1]; var col=(last>=5)?"rgba(74,222,128,0.55)":((last<=-5)?"rgba(248,113,113,0.55)":"rgba(200,169,110,0.35)"); if(last>=5) hitU++; if(last<=-5) hitL++; trs.push({x:t,y:path,mode:"lines",line:{color:col,width:1.5},showlegend:false,hoverinfo:"skip"});}
  trs.push({x:[0,200],y:[5,5],mode:"lines",line:{color:"#4ade80",width:2,dash:"dash"},name:"ust sinir +5"});
